23	// testProxy creates a Proxy pointed at a single test server for
24	// /et/owner/repo. token is left empty so SetAuth no-ops — these tests
25	// exercise the plumbing (HTTP method, path, body), not the auth flow.
26	func testProxy(server *httptest.Server) *Proxy {
27		return New(Config{
28			Nodes: replicas.NodeConfig{
29				InitialNodes: []string{server.URL},
30				EntryURL:     server.URL,
31				ClusterHost:  mustHost(nil, server.URL),
32				RepoPath:     "owner/repo",
33			},
34			Path: "/et/owner/repo",
35		})
36	}
