38	func proxyWithClient(nodes []string, path, entryURL, clusterHost string, client *http.Client) *Proxy {
39		p := New(Config{
40			Nodes: replicas.NodeConfig{
41				InitialNodes: nodes,
42				EntryURL:     entryURL,
43				ClusterHost:  clusterHost,
44				RepoPath:     "owner/repo",
45			},
46			Path: path,
47		})
48		if client != nil {
49			// Swap in the test-provided client (e.g. one we want to
50			// inspect or one with a custom CheckRedirect). Point the
51			// discovery probe at the same transport so the cold info/refs
52			// path honors the test's TLS trust / routing instead of the
53			// real-network discovery transport New wired up.
54			p.client = client
55			p.discoveryTransport = client.Transport
56		}
57		return p
58	}
