60	// mustHost returns the hostname portion of a URL, stripping the port.
61	func mustHost(t *testing.T, raw string) string {
62		if t != nil {
63			t.Helper()
64		}
65		u, err := url.Parse(raw)
66		if err != nil {
67			if t != nil {
68				t.Fatalf("parse %q: %v", raw, err)
69			}
70			return ""
71		}
72		return u.Hostname()
73	}
